<script setup lang="ts">
type Color = { hex: string; alpha: number; rgba_hex: string; pixel_count: number; visible_pixel_fraction: number }
type Row = { path: string; caption: string; folder: string; name: string; position: number; image_url: string; annotated: boolean; metadata?: Record<string, any> | null; annotation?: { asset_id?: string; labels?: Record<string, any>; caption_candidate?: string; color_measurements?: { status?: string; source_size?: number[]; palette_hex?: Color[] }; need_rework?: boolean; review_status?: string; model?: string; [key: string]: any } | null }
type Result = { total:number; filtered:number; offset:number; rows:Row[] }
const route=useRoute(), router=useRouter()
const search=ref(''), onlyAnnotated=ref(false), thumbnailSize=ref('medium'), result=ref<Result | null>(null), selected=ref<Row | null>(null), loading=ref(false), error=ref(''), detailsError=ref('')
const measured=ref<Color[]>([]), dimensions=ref(''), paletteStatus=ref(''), pageSize=24
let timer: ReturnType<typeof setTimeout> | undefined, requestId=0, detailId=0
const fmt=(n:number)=>n.toLocaleString('fr-FR')
const page=computed(()=>{const value=route.query.page; if(typeof value!=='string' || !/^[1-9]\d*$/.test(value)) return 1; const n=Number(value); return Number.isSafeInteger(n) && n <= Math.floor(Number.MAX_SAFE_INTEGER/pageSize) ? n : 1})
const offset=computed(()=>(page.value-1)*pageSize)
const pages=computed(()=>Math.max(1,Math.ceil((result.value?.filtered || 0)/pageSize)))
const pct=(n:number)=>`${(n*100).toFixed(1)} %`
async function load() { const id=++requestId; loading.value=true; error.value=''; try { const data=await $fetch<Result>('/api/catalog',{query:{offset:offset.value,limit:pageSize,search:search.value,annotated:onlyAnnotated.value?'1':''}}); if(id!==requestId)return; const last=Math.max(1,Math.ceil(data.filtered/pageSize)); if(page.value>last){await goToPage(last,true);return} result.value=data } catch { if(id===requestId) error.value='Impossible de charger la galerie.' } finally { if(id===requestId) loading.value=false } }
function goToPage(value:number,replace=false){const query={...route.query,page:String(value)};return replace?router.replace({query}):router.push({query})}
function reset(){if(page.value!==1)void goToPage(1,true);else void load()}
watch(search,()=>{clearTimeout(timer);timer=setTimeout(reset,300)})
watch(onlyAnnotated,reset)
watch(page,()=>{void load()})
async function openAt(position:number) {
 const id=++detailId; detailsError.value=''; measured.value=[]; dimensions.value=''; paletteStatus.value='Chargement…'
 try { const data=await $fetch<Result>('/api/catalog',{query:{offset:position,limit:1,search:search.value,annotated:onlyAnnotated.value?'1':'',detail:'1'}}); if(id!==detailId)return; selected.value=data.rows[0] || null; if(selected.value) void measure(selected.value,id) } catch { if(id===detailId) detailsError.value='Impossible de charger les détails.' }
}
function measure(row:Row,id:number){
 const saved=row.annotation?.color_measurements
 if(saved?.status==='measured' && saved.palette_hex){measured.value=saved.palette_hex;dimensions.value=saved.source_size?.join(' × ') || '';paletteStatus.value='Mesurée depuis le PNG source';return}
 const image=new Image();image.onload=()=>{if(id!==detailId)return;try{const canvas=document.createElement('canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;const ctx=canvas.getContext('2d',{willReadFrequently:true});if(!ctx)throw Error();ctx.drawImage(image,0,0);const data=ctx.getImageData(0,0,canvas.width,canvas.height).data;const counts=new Map<string,number>();let total=0;for(let i=0;i<data.length;i+=4){const a=data[i+3]!;if(!a)continue;const hex='#'+[data[i],data[i+1],data[i+2],a].map(v=>v!.toString(16).padStart(2,'0')).join('').toUpperCase();counts.set(hex,(counts.get(hex)||0)+1);total++}measured.value=[...counts.entries()].sort((a,b)=>b[1]-a[1]).map(([rgba_hex,pixel_count])=>({hex:rgba_hex.slice(0,7),rgba_hex,alpha:parseInt(rgba_hex.slice(7),16),pixel_count,visible_pixel_fraction:pixel_count/total}));dimensions.value=`${canvas.width} × ${canvas.height}`;paletteStatus.value='Calculée depuis l’image affichée'}catch{paletteStatus.value='Palette indisponible'}};image.onerror=()=>{if(id===detailId)paletteStatus.value='Image indisponible'};image.src=row.image_url
}
function close(){detailId++;selected.value=null}
function move(delta:number){if(!selected.value)return;const next=selected.value.position+delta;if(next>=0 && next<(result.value?.filtered||0)) void openAt(next)}
function keys(e:KeyboardEvent){if(!selected.value)return;if(e.key==='Escape')close();if(e.key==='ArrowRight')move(1);if(e.key==='ArrowLeft')move(-1)}
onMounted(()=>{void load();window.addEventListener('keydown',keys)})
onUnmounted(()=>{clearTimeout(timer);window.removeEventListener('keydown',keys)})
</script>
<template>
 <main class="explore-shell"><header class="explore-header"><NuxtLink to="/" class="brand">IRIS <span>/ DATASET</span></NuxtLink><nav><NuxtLink to="/">Vue d’ensemble</NuxtLink><NuxtLink to="/galerie" class="active">Galerie</NuxtLink></nav></header>
 <div class="gallery-toolbar"><label class="gallery-search"><span>⌕</span><input v-model="search" type="search" placeholder="Rechercher un jeu, un sprite, une description…"></label><span v-if="result" class="gallery-count">{{ fmt(result.filtered) }} IMAGES</span><label class="gallery-size">Taille <select v-model="thumbnailSize"><option value="small">Petite</option><option value="medium">Moyenne</option><option value="large">Grande</option></select></label><label class="gallery-toggle"><input v-model="onlyAnnotated" type="checkbox"> Annotées par Qwen</label></div>
 <p v-if="error" class="notice">{{ error }}</p><p v-else-if="loading && !result" class="notice">Chargement de la galerie…</p><div v-else class="sprite-grid" :class="`sprite-grid--${thumbnailSize}`"><button v-for="row in result?.rows || []" :key="row.path" class="sprite-card" @click="openAt(row.position)"><div class="sprite-preview"><img :src="row.image_url" :alt="row.name" loading="lazy"><span v-if="row.annotated" class="annotated-dot" title="Annotation Qwen disponible">✳</span></div><div class="sprite-info"><strong>{{ row.name }}</strong><span>{{ row.folder.replaceAll('_',' ') }}</span></div></button></div>
 <p v-if="result && !result.rows.length" class="notice">Aucune image ne correspond à cette recherche.</p>
 <nav v-if="result" class="gallery-pagination" aria-label="Pagination de la galerie"><button :disabled="page<=1 || loading" @click="goToPage(page-1)">← Précédent</button><span>PAGE {{ page }} / {{ pages }}</span><button :disabled="page>=pages || loading" @click="goToPage(page+1)">Suivant →</button></nav>
 <Teleport to="body"><div v-if="selected" class="lightbox" role="dialog" aria-modal="true" aria-label="Détails de l’image" @click.self="close"><div class="lightbox-panel"><div class="lightbox-top"><span>{{ fmt(selected.position + 1) }} / {{ fmt(result?.filtered || 0) }} · {{ selected.folder }}</span><button class="icon-button" aria-label="Fermer" @click="close">×</button></div><div class="lightbox-content"><div class="lightbox-visual"><button class="carousel-arrow left" aria-label="Image précédente" :disabled="selected.position===0" @click="move(-1)">←</button><img :src="selected.image_url" :alt="selected.name"><button class="carousel-arrow right" aria-label="Image suivante" :disabled="selected.position >= (result?.filtered || 0)-1" @click="move(1)">→</button><span class="visual-size">{{ dimensions ? dimensions + ' PX' : 'IMAGE SOURCE' }}</span></div><div class="lightbox-details"><p class="kicker">IMAGE SOURCE / {{ selected.folder.replaceAll('_',' ') }}</p><h2>{{ selected.name }}</h2><p class="file-path">{{ selected.path }}</p><p v-if="detailsError" class="notice">{{ detailsError }}</p><div class="detail-block"><span class="detail-label">DESCRIPTION QWEN3.8</span><p v-if="selected.annotation?.caption_candidate">{{ selected.annotation.caption_candidate }}</p><p v-else class="muted">Aucune annotation Qwen3.8 pour cette image.</p></div><div v-if="selected.caption" class="detail-block"><span class="detail-label">LÉGENDE SOURCE</span><p>{{ selected.caption }}</p></div><div class="detail-block"><span class="detail-label">PALETTE EXACTE · {{ measured.length }} COULEURS</span><p class="muted">{{ paletteStatus }} · pixels visibles</p><div class="detail-swatches"><span v-for="c in measured.slice(0, 60)" :key="c.rgba_hex" :style="{background:c.hex,opacity:c.alpha/255}" :title="`${c.rgba_hex} · ${pct(c.visible_pixel_fraction)}`" /></div><details v-if="measured.length"><summary>Voir les codes et proportions</summary><div class="hex-list"><div v-for="c in measured" :key="c.rgba_hex"><i :style="{background:c.hex,opacity:c.alpha/255}"/><code>{{ c.rgba_hex }}</code><span>{{ fmt(c.pixel_count) }} px · {{ pct(c.visible_pixel_fraction) }}</span></div></div></details></div><div v-if="selected.metadata" class="detail-block"><span class="detail-label">MÉTADONNÉES SOURCE</span><div class="detail-tags"><div v-for="(value,key) in selected.metadata" :key="String(key)"><template v-if="value !== null && value !== undefined && value !== '' && typeof value !== 'object'"><span>{{ String(key).replaceAll('_',' ') }}</span><strong>{{ value }}</strong></template></div></div><details><summary>Métadonnées complètes</summary><pre class="raw-json">{{ JSON.stringify(selected.metadata, null, 2) }}</pre></details></div><div v-if="selected.annotation" class="detail-block"><span class="detail-label">TAXONOMIE QWEN3.8</span><div class="detail-tags"><div v-for="(value,key) in selected.annotation.labels || {}" :key="String(key)"><span>{{ String(key).replaceAll('_',' ') }}</span><strong>{{ Array.isArray(value) ? value.join(', ') : value }}</strong></div><div><span>Besoin de retouche</span><strong>{{ selected.annotation.need_rework === true ? 'Oui' : selected.annotation.need_rework === false ? 'Non' : 'Inconnu' }}</strong></div><div><span>Statut</span><strong>{{ selected.annotation.review_status || 'inconnu' }}</strong></div><div><span>Modèle</span><strong>{{ selected.annotation.model }}</strong></div></div><details><summary>Annotation complète</summary><pre class="raw-json">{{ JSON.stringify(selected.annotation, null, 2) }}</pre></details></div></div></div><div class="lightbox-bottom"><span>← → pour naviguer · Échap pour fermer</span><div><button :disabled="selected.position===0" @click="move(-1)">← Précédent</button><button :disabled="selected.position >= (result?.filtered || 0)-1" @click="move(1)">Suivant →</button></div></div></div></div></Teleport>
 <footer class="explore-footer">IRIS DATASET LAB <span>Explore les détails, un pixel à la fois.</span></footer></main>
</template>
